using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
namespace TextureFlow.UnityEditor {
 [Serializable] public class FlowConfig { public int schemaVersion=1;public float speed=.1f,angle=90,tilingX=1,tilingY=1,rotation=0,emission=2,hdr=0;public string tint="#40DFFF",shader="TextureFlow fallback"; }
 [InitializeOnLoad] public static class FlowImporter {
  static bool queued;static double nextScan;
  static FlowImporter(){EditorApplication.update+=Tick;Queue();}
  static void Tick(){if(EditorApplication.timeSinceStartup<nextScan)return;nextScan=EditorApplication.timeSinceStartup+2;if(Directory.Exists("Assets/TextureFlow/Exports")){bool pending=Directory.GetFiles("Assets/TextureFlow/Exports","flow-request.json",SearchOption.AllDirectories).Any(f=>!File.Exists(Path.Combine(Path.GetDirectoryName(f),"flow-result.json"))||File.GetLastWriteTimeUtc(f)>File.GetLastWriteTimeUtc(Path.Combine(Path.GetDirectoryName(f),"flow-result.json")));if(pending){AssetDatabase.Refresh();Queue();}}}
  public static void Queue(){if(queued)return;queued=true;EditorApplication.delayCall+=Process;}
  static void Process(){queued=false;if(EditorApplication.isCompiling||EditorApplication.isUpdating){Queue();return;}if(!Directory.Exists("Assets/TextureFlow/Exports"))return;foreach(string f in Directory.GetFiles("Assets/TextureFlow/Exports","flow-request.json",SearchOption.AllDirectories)){string result=Path.Combine(Path.GetDirectoryName(f),"flow-result.json");if(File.Exists(result)&&File.GetLastWriteTimeUtc(result)>=File.GetLastWriteTimeUtc(f))continue;try{string message=Import(f);File.WriteAllText(result,JsonUtility.ToJson(new Result{success=true,message=message},true));}catch(Exception ex){Debug.LogError("Texture Flow: "+ex);File.WriteAllText(result,JsonUtility.ToJson(new Result{success=false,message=ex.Message},true));}}AssetDatabase.SaveAssets();}
  [Serializable] class Result {public bool success;public string message;}
  static string AssetPath(string folder,string name){return (folder+"/"+name).Replace('\\','/');}
  static Texture2D Texture(string folder,string file,bool linear,bool repeat){string path=AssetPath(folder,file);var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(importer==null)throw new Exception("Texture not imported: "+path);importer.textureType=TextureImporterType.Default;importer.sRGBTexture=!linear;importer.alphaSource=TextureImporterAlphaSource.FromInput;importer.alphaIsTransparency=false;importer.wrapMode=repeat?TextureWrapMode.Repeat:TextureWrapMode.Clamp;importer.maxTextureSize=8192;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.npotScale=TextureImporterNPOTScale.None;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
  static void Require(Material m,params string[] names){foreach(string n in names)if(!m.HasProperty(n))throw new Exception("Shader version lacks "+n+". Use TextureFlow fallback.");}
  public static string Import(string request){var c=JsonUtility.FromJson<FlowConfig>(File.ReadAllText(request));if(c==null||c.schemaVersion!=1)throw new Exception("Unsupported export schema.");if(!ColorUtility.TryParseHtmlString(c.tint,out Color tint))throw new Exception("Invalid tint.");string dir=Path.GetDirectoryName(request).Replace('\\','/');var original=Texture(dir,"base.png",false,false);var flow=Texture(dir,"flow.png",false,true);var mask=Texture(dir,"mask.png",true,false);Texture(dir,"cutout.png",false,false);
   var shader=Shader.Find("TextureFlow/Masked Scroll");if(shader==null)throw new Exception("Texture Flow shader is missing.");var m=new Material(shader);float rad=c.angle*Mathf.Deg2Rad;var velocity=new Vector4(Mathf.Cos(rad)*c.speed,Mathf.Sin(rad)*c.speed,0,0);float strength=c.emission*Mathf.Pow(2,c.hdr);
   m.SetTexture("_MainTex",original);m.SetTexture("_FlowTex",flow);m.SetTexture("_Mask",mask);m.SetTextureScale("_FlowTex",new Vector2(c.tilingX,c.tilingY));m.SetVector("_Velocity",velocity);m.SetFloat("_Rotation",c.rotation*Mathf.Deg2Rad);m.SetColor("_Tint",tint);m.SetFloat("_Emission",strength);
   string message="Created fixed-mask animated material.";string path=AssetPath(dir,"Animated.mat");var existing=AssetDatabase.LoadAssetAtPath<Material>(path);if(existing==null)AssetDatabase.CreateAsset(m,path);else{EditorUtility.CopySerialized(m,existing);UnityEngine.Object.DestroyImmediate(m);m=existing;}
   if(c.shader!="TextureFlow fallback") {Material native=null;try{if(c.shader=="Poiyomi"){shader=Shader.Find(".poiyomi/Poiyomi Toon")??Shader.Find("Poiyomi/Poiyomi Toon");}else shader=Shader.Find("lilToon");if(shader==null)throw new Exception(c.shader+" is not installed.");if(c.rotation!=0)throw new Exception("Native rotation mapping is not validated; fallback retains exact rotation.");native=new Material(shader);Require(native,"_MainTex","_EmissionMap","_EmissionColor");native.SetTexture("_MainTex",original);native.SetTexture("_EmissionMap",flow);native.SetTextureScale("_EmissionMap",new Vector2(c.tilingX,c.tilingY));
    if(c.shader=="Poiyomi"){Require(native,"_EnableEmission","_EmissionMask","_EmissionMapPan","_EmissionStrength","_EmissionReplace0");native.SetFloat("_EnableEmission",1);native.EnableKeyword("_EMISSION");native.SetTexture("_EmissionMask",mask);native.SetVector("_EmissionMapPan",-velocity);native.SetColor("_EmissionColor",tint);native.SetFloat("_EmissionStrength",strength);native.SetFloat("_EmissionReplace0",1);}
    else {Require(native,"_UseEmission","_EmissionBlendMask","_EmissionMap_ScrollRotate");native.SetFloat("_UseEmission",1);native.SetTexture("_EmissionBlendMask",mask);native.SetVector("_EmissionMap_ScrollRotate",-velocity);native.SetColor("_EmissionColor",tint*Mathf.Max(strength,0));if(native.HasProperty("_EmissionBlendMode"))native.SetFloat("_EmissionBlendMode",0);}
    string np=AssetPath(dir,"Native.mat");var ne=AssetDatabase.LoadAssetAtPath<Material>(np);if(ne==null)AssetDatabase.CreateAsset(native,np);else{EditorUtility.CopySerialized(native,ne);UnityEngine.Object.DestroyImmediate(native);}message+=" Native material created; verify appearance with your installed shader version.";
   }catch(Exception ex){if(native!=null&&!AssetDatabase.Contains(native))UnityEngine.Object.DestroyImmediate(native);message+=" "+ex.Message+" Animated.mat uses the built-in fallback.";Debug.LogWarning("Texture Flow: "+message);}}
   EditorUtility.SetDirty(m);AssetDatabase.SaveAssets();return message;
  }
 }
 public class FlowPostprocessor : AssetPostprocessor {static void OnPostprocessAllAssets(string[] imported,string[] deleted,string[] moved,string[] from){if(imported.Any(p=>p.EndsWith("flow-request.json",StringComparison.Ordinal)))FlowImporter.Queue();}}
 public class FlowWindow : EditorWindow {
  Material generated;Renderer target;int slot;
  [MenuItem("Tools/Texture Flow/Apply Animated Material")] public static void Open(){GetWindow<FlowWindow>("Texture Flow");}
  void OnGUI(){GUILayout.Label("Texture Flow • apply to one avatar slot",EditorStyles.boldLabel);EditorGUILayout.HelpBox("Select an exported Animated.mat (exact composite) or Native.mat, then the avatar Renderer and material slot. Undo is supported. Glow depends on world bloom. PC shaders only.",MessageType.Info);generated=(Material)EditorGUILayout.ObjectField("Generated material",generated,typeof(Material),false);target=(Renderer)EditorGUILayout.ObjectField("Avatar renderer",target,typeof(Renderer),true);slot=EditorGUILayout.IntField("Material slot",slot);if(target!=null){var mats=target.sharedMaterials;for(int i=0;i<mats.Length;i++)EditorGUILayout.LabelField(i+": "+(mats[i]==null?"Empty":mats[i].name));}using(new EditorGUI.DisabledScope(generated==null||target==null||slot<0||slot>=target.sharedMaterials.Length)){if(GUILayout.Button("Apply to this slot")){Undo.RecordObject(target,"Apply Texture Flow material");var mats=target.sharedMaterials;mats[slot]=generated;target.sharedMaterials=mats;PrefabUtility.RecordPrefabInstancePropertyModifications(target);EditorUtility.SetDirty(target);}}if(GUILayout.Button("Use selected material"))generated=Selection.activeObject as Material;if(GUILayout.Button("Process pending exports"))FlowImporter.Queue();}
 }
}
